// @FIGURE_CODE_BEGIN
(function () {
  var SVGNS = 'http://www.w3.org/2000/svg';
  var BLUE = '#1a9fe0', DARKBLUE = '#1478c8', RED = '#ee3b2f';
  var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
  draw.viewbox(0, 0, 1240, 1080).attr('preserveAspectRatio', 'xMidYMid meet');

  var gRibbon = draw.group(), gFence = draw.group(), gCurve = draw.group(),
      gDots = draw.group(), gInset = draw.group(), gAnno = draw.group(),
      gLabels = draw.group(), gPanel = draw.group(), gStatic = draw.group();

  /* ---------------- curve geometry ---------------- */
  var CP = [[48,860],[160,795],[262,722],[352,632],[420,530],[452,430],[440,330],
            [388,246],[300,208],[208,232],[155,312],[168,400],[248,442],[340,430],
            [412,380],[468,322],[512,240],[545,148],[566,62]];

  function crPoint(p0,p1,p2,p3,t){
    var t2=t*t,t3=t2*t;
    return {
      x:0.5*((2*p1[0])+(-p0[0]+p2[0])*t+(2*p0[0]-5*p1[0]+4*p2[0]-p3[0])*t2+(-p0[0]+3*p1[0]-3*p2[0]+p3[0])*t3),
      y:0.5*((2*p1[1])+(-p0[1]+p2[1])*t+(2*p0[1]-5*p1[1]+4*p2[1]-p3[1])*t2+(-p0[1]+3*p1[1]-3*p2[1]+p3[1])*t3)
    };
  }
  var PTS = [];
  (function(){
    var ext=[CP[0]].concat(CP,[CP[CP.length-1]]);
    for(var i=0;i+3<ext.length;i++){
      for(var j=0;j<50;j++) PTS.push(crPoint(ext[i],ext[i+1],ext[i+2],ext[i+3],j/50));
    }
    PTS.push({x:CP[CP.length-1][0],y:CP[CP.length-1][1]});
  })();
  var CUM=[0];
  for(var ci=1;ci<PTS.length;ci++) CUM.push(CUM[ci-1]+Math.hypot(PTS[ci].x-PTS[ci-1].x,PTS[ci].y-PTS[ci-1].y));
  var L=CUM[CUM.length-1];

  function pointAt(s){
    s=Math.max(0,Math.min(L,s));
    var lo=0,hi=CUM.length-1;
    while(lo<hi-1){var m=(lo+hi)>>1; if(CUM[m]<=s) lo=m; else hi=m;}
    var d=CUM[hi]-CUM[lo], t=d>0?(s-CUM[lo])/d:0;
    return {x:PTS[lo].x+(PTS[hi].x-PTS[lo].x)*t, y:PTS[lo].y+(PTS[hi].y-PTS[lo].y)*t};
  }
  function tanAt(s){
    var a=pointAt(Math.max(0,s-2)), b=pointAt(Math.min(L,s+2));
    var dx=b.x-a.x, dy=b.y-a.y, m=Math.hypot(dx,dy)||1;
    return {x:dx/m,y:dy/m};
  }
  function rnorm(t){ return {x:-t.y, y:t.x}; }          // outward on the loop
  function arcPoints(s1,s2,m){ var o=[]; for(var i=0;i<=m;i++) o.push(pointAt(s1+(s2-s1)*i/m)); return o; }
  function ptsStr(a){ return a.map(function(p){return p.x+','+p.y;}).join(' '); }

  /* self-intersection (for the over/under gap) */
  var XSEC=null;
  (function(){
    var st=5;
    for(var i=0;i+st<PTS.length;i+=st){
      for(var j=i+12*st;j+st<PTS.length;j+=st){
        var r=segInt(PTS[i],PTS[i+st],PTS[j],PTS[j+st]);
        if(r){ XSEC={si:CUM[i]+r.t*(CUM[i+st]-CUM[i]), sj:CUM[j]+r.u*(CUM[j+st]-CUM[j]), x:r.x, y:r.y}; return; }
      }
    }
  })();
  function segInt(p,p2,q,q2){
    var r={x:p2.x-p.x,y:p2.y-p.y}, s={x:q2.x-q.x,y:q2.y-q.y};
    var den=r.x*s.y-r.y*s.x; if(Math.abs(den)<1e-9) return null;
    var t=((q.x-p.x)*s.y-(q.y-p.y)*s.x)/den, u=((q.x-p.x)*r.y-(q.y-p.y)*r.x)/den;
    if(t>=0&&t<=1&&u>=0&&u<=1) return {t:t,u:u};
    return null;
  }

  /* ---------------- density ---------------- */
  function fAt(p){
    var wx=p.x/100, wy=(1080-p.y)/100;
    var d2=(wx-3.0)*(wx-3.0)+(wy-7.4)*(wy-7.4);
    return 0.55+1.25*Math.exp(-d2/6)+0.30*Math.sin(0.9*wx+0.6);
  }
  var FMIN=1e9,FMAX=-1e9,EXACT=0;
  (function(){
    var M=4000;
    for(var i=0;i<M;i++){
      var s=L*(i+0.5)/M, v=fAt(pointAt(s));
      if(v<FMIN)FMIN=v; if(v>FMAX)FMAX=v;
      EXACT+=v*(L/M)/100;
    }
  })();
  function hex(c){ return [parseInt(c.substr(1,2),16),parseInt(c.substr(3,2),16),parseInt(c.substr(5,2),16)]; }
  function mix(a,b,t){ var A=hex(a),B=hex(b);
    return 'rgb('+Math.round(A[0]+(B[0]-A[0])*t)+','+Math.round(A[1]+(B[1]-A[1])*t)+','+Math.round(A[2]+(B[2]-A[2])*t)+')'; }
  function colorFor(v){
    var t=(v-FMIN)/(FMAX-FMIN); t=Math.max(0,Math.min(1,t));
    return t<0.5 ? mix('#1a9fe0','#f4b942',t/0.5) : mix('#f4b942','#e8482c',(t-0.5)/0.5);
  }

  /* ---------------- math text ---------------- */
  function mathText(parent,x,y,parts,size,opts){
    opts=opts||{};
    var t=document.createElementNS(SVGNS,'text');
    t.setAttribute('x',x); t.setAttribute('y',y);
    t.setAttribute('text-anchor',opts.anchor||'start');
    t.setAttribute('font-family','Georgia,"Times New Roman",serif');
    t.setAttribute('font-size',size);
    t.setAttribute('fill',opts.color||'#111');
    if(opts.halo!==false){
      t.setAttribute('paint-order','stroke');
      t.setAttribute('stroke','#fff');
      t.setAttribute('stroke-width',opts.haloW==null?5:opts.haloW);
      t.setAttribute('stroke-linejoin','round');
    }
    var cur=0;
    parts.forEach(function(p){
      var kind=p[1]||'i';
      var sup=(kind==='sup'), sub=(!sup && kind.charAt(0)==='s');
      var target=sub?size*0.30:(sup?-size*0.44:0);
      var fs=(sub||sup)?size*0.68:size;
      var ts=document.createElementNS(SVGNS,'tspan');
      ts.textContent=p[0];
      ts.setAttribute('font-size',fs);
      ts.setAttribute('font-style',(kind==='r'||kind==='sr'||kind==='sup')?'normal':'italic');
      var dy=target-cur; if(dy!==0) ts.setAttribute('dy',dy);
      cur=target; t.appendChild(ts);
    });
    parent.node.appendChild(t);
    return SVG(t);
  }
  function P_(sub){ return [['P','i'],[sub,'sr']]; }
  var PARTS={
    P0:[['P','i'],[' = ','r'],['P','i'],['0','sr']],
    Q :[['Q','i'],[' = ','r'],['P','i'],['n','si']],
    Pk:[['P','i'],['k','si']],
    Pk1:[['P','i'],['k','si'],['−1','sr']],
    Pn1:[['P','i'],['n','si'],['−1','sr']],
    ds:[['Δ','r'],['s','i'],['k','sr']],
    mass:[['Mass ','r'],['Δ','r'],['M','i'],['k','sr']],
    star:[['P','i'],['k','si'],['*','sup'],['(','r'],['x','i'],['k','sr'],['*','sup'],[', ','r'],
          ['y','i'],['k','sr'],['*','sup'],[', ','r'],['z','i'],['k','sr'],['*','sup'],[')','r']],
    formula:[['Δ','r'],['M','i'],['k','sr'],[' ≈ ','r'],['f','i'],['(','r'],['x','i'],['k','sr'],['*','sup'],[', ','r'],
             ['y','i'],['k','sr'],['*','sup'],[', ','r'],['z','i'],['k','sr'],['*','sup'],[')','r'],
             [' ','r'],['Δ','r'],['s','i'],['k','sr']]
  };

  /* ---------------- small drawing helpers ---------------- */
  function head(g,x,y,dx,dy,size,color){
    var a=Math.atan2(dy,dx);
    var p=[[x,y],[x-size*Math.cos(a-0.38),y-size*Math.sin(a-0.38)],[x-size*Math.cos(a+0.38),y-size*Math.sin(a+0.38)]];
    g.polygon(p.map(function(q){return q[0]+','+q[1];}).join(' ')).fill(color);
  }
  function doubleArrow(g,a,b,color,w,hs){
    g.line(a.x,a.y,b.x,b.y).stroke({color:color,width:w,linecap:'round'});
    head(g,b.x,b.y,b.x-a.x,b.y-a.y,hs,color);
    head(g,a.x,a.y,a.x-b.x,a.y-b.y,hs,color);
  }
  function tick(g,p,nv,o1,o2,color){
    g.line(p.x+nv.x*o1,p.y+nv.y*o1,p.x+nv.x*o2,p.y+nv.y*o2).stroke({color:color,width:2.6,linecap:'round'});
  }

  /* ribbon arrow */
  function ribbonPath(A,C,B,w0,w1,wingF){
    var N=48, tB=0.86, cen=[],nor=[];
    for(var i=0;i<=N;i++){
      var t=tB*i/N, mt=1-t;
      var x=mt*mt*A.x+2*mt*t*C.x+t*t*B.x, y=mt*mt*A.y+2*mt*t*C.y+t*t*B.y;
      var dx=2*mt*(C.x-A.x)+2*t*(B.x-C.x), dy=2*mt*(C.y-A.y)+2*t*(B.y-C.y);
      var m=Math.hypot(dx,dy)||1;
      cen.push({x:x,y:y}); nor.push({x:-dy/m,y:dx/m});
    }
    var left=[],right=[];
    for(var j=0;j<=N;j++){
      var w=w0+(w1-w0)*(j/N);
      left.push({x:cen[j].x+nor[j].x*w,y:cen[j].y+nor[j].y*w});
      right.push({x:cen[j].x-nor[j].x*w,y:cen[j].y-nor[j].y*w});
    }
    var e=cen[N], en=nor[N];
    var wl={x:e.x+en.x*w1*wingF,y:e.y+en.y*w1*wingF};
    var wr={x:e.x-en.x*w1*wingF,y:e.y-en.y*w1*wingF};
    var poly=left.concat([wl,B,wr]).concat(right.slice().reverse());
    return poly;
  }

  /* ---------------- state ---------------- */
  var N=8,K=5,U=0.5,MODE='geom';
  var insetPts=[],insetCum=[],dragging=false;

  /* ---------------- static furniture ---------------- */
  (function(){
    gStatic.rect(530,92).move(170,948).fill('#fff').stroke({color:'#9a9a9a',width:3});
    mathText(gStatic,435,1010,PARTS.formula,36,{anchor:'middle',halo:false});
    var hit=gStatic.rect(530,92).move(170,948).fill('#fff').opacity(0).css('cursor','pointer');
    hit.on('mousemove',function(e){showTooltip('Mass of one arc ≈ density at the sample point × arc length',e);})
       .on('mouseleave',hideTooltip)
       .on('click',function(){showPopup('The key approximation',
         'Over a very short arc the density f barely changes, so the mass of that arc is approximately f evaluated at ANY point of the arc times the arc length Δsₖ. Summing these products over all arcs gives a Riemann sum; its limit as n → ∞ is the line integral ∫_C f ds.');});
  })();

  /* ---------------- main redraw ---------------- */
  function redraw(){
    [gRibbon,gFence,gCurve,gDots,gInset,gAnno,gLabels,gPanel].forEach(function(g){g.clear();});

    var sArr=[]; for(var i=0;i<=N;i++) sArr.push(L*i/N);
    var s1=sArr[K-1], s2=sArr[K], arcLen=s2-s1;
    var arcPts=arcPoints(s1,s2,80);
    var HF=48;

    /* ---- fences (density / Riemann) ---- */
    if(MODE!=='geom'){
      var M=320, prev=null, prevTop=null;
      var outline=[];
      for(var q=0;q<=M;q++){
        var s=L*q/M, p=pointAt(s), nv=rnorm(tanAt(s)), fv=fAt(p);
        var tp={x:p.x+nv.x*fv*HF, y:p.y+nv.y*fv*HF};
        outline.push(tp);
        if(MODE==='density' && prev){
          gFence.polygon(ptsStr([prev,prevTop,tp,p])).fill({color:colorFor(fv),opacity:0.32}).stroke('none');
        }
        prev=p; prevTop=tp;
      }
      gFence.polyline(ptsStr(outline)).fill('none')
        .stroke({color:'#c77a1e',width:2.4,opacity:0.85,dasharray:'8,6'});
      if(MODE==='riemann'){
        for(var a=0;a<N;a++){
          var ss=sArr[a], se=sArr[a+1];
          var sp=pointAt(ss+(se-ss)*U), fv2=fAt(sp);
          var base=arcPoints(ss,se,14), top=[];
          for(var b=0;b<base.length;b++){
            var s3=ss+(se-ss)*b/(base.length-1), nv3=rnorm(tanAt(s3));
            top.push({x:base[b].x+nv3.x*fv2*HF, y:base[b].y+nv3.y*fv2*HF});
          }
          gFence.polygon(ptsStr(base.concat(top.slice().reverse())))
            .fill({color:colorFor(fv2),opacity:0.45}).stroke({color:'#ffffff',width:1.6});
        }
      }
    }

    /* ---- curve ---- */
    if(MODE==='geom'){
      gCurve.polyline(ptsStr(PTS)).fill('none').stroke({color:BLUE,width:7,linecap:'round',linejoin:'round'});
    }else{
      var step=14;
      for(var s=0;s<L;s+=step){
        var e=Math.min(L,s+step+1.5);
        var seg=arcPoints(s,e,3);
        gCurve.polyline(ptsStr(seg)).fill('none')
          .stroke({color:colorFor(fAt(pointAt((s+e)/2))),width:7,linecap:'round'});
      }
    }
    if(XSEC){
      gCurve.circle(22).center(XSEC.x,XSEC.y).fill('#fff');
      var gs=Math.max(0,XSEC.sj-46), ge=Math.min(L,XSEC.sj+46);
      var over=arcPoints(gs,ge,16);
      gCurve.polyline(ptsStr(over)).fill('none')
        .stroke({color:MODE==='geom'?BLUE:colorFor(fAt(pointAt(XSEC.sj))),width:7,linecap:'round'});
    }

    /* ---- highlighted arc ---- */
    gCurve.polyline(ptsStr(arcPts)).fill('none').stroke({color:'#9fd8f5',width:16,linecap:'round',linejoin:'round'});
    var hArc=gCurve.polyline(ptsStr(arcPts)).fill('none')
      .stroke({color:DARKBLUE,width:8,linecap:'round',linejoin:'round'}).css('cursor','pointer');
    hArc.on('mousemove',function(e){showTooltip('The kth arc: from Pₖ₋₁ to Pₖ, arc length Δsₖ ≈ '+(arcLen/100).toFixed(2),e);})
        .on('mouseleave',hideTooltip)
        .on('click',function(){showPopup('The kth arc',
          'Every arc of the partition plays exactly the same role. Its length is Δsₖ and the wire it carries has mass ΔMₖ. The magnified inset at lower right is just this one representative piece.');});

    /* ---- partition dots ---- */
    var dr = N>26 ? 4.5 : (N>14 ? 6.5 : 9);
    for(var d=0;d<=N;d++){
      var pd=pointAt(sArr[d]);
      gDots.circle(dr*2).center(pd.x,pd.y).fill(BLUE);
    }
    var pA=pointAt(s1), pB=pointAt(s2);
    gDots.circle(dr*2.3).center(pA.x,pA.y).fill(DARKBLUE);
    gDots.circle(dr*2.3).center(pB.x,pB.y).fill(DARKBLUE);

    /* ---- sample points on the main curve ---- */
    var sSample=s1+arcLen*U;
    if(MODE!=='geom'){
      for(var a2=0;a2<N;a2++){
        var sp2=pointAt(sArr[a2]+(sArr[a2+1]-sArr[a2])*U);
        gDots.circle(11).center(sp2.x,sp2.y).fill(RED).opacity(0.9);
      }
    }
    var spMain=pointAt(sSample);
    gDots.circle(15).center(spMain.x,spMain.y).fill(RED).stroke({color:'#fff',width:2});

    /* ---- Δs bracket on the highlighted arc ---- */
    var mid=pointAt((s1+s2)/2), tm=tanAt((s1+s2)/2), nm=rnorm(tm);
    var inN={x:-nm.x,y:-nm.y};                       // interior / left side
    var bOff = (MODE==='geom') ? 30 : 62;
    if(arcLen>85){
      tick(gAnno,pA,inN,bOff-16,bOff+20,'#000');
      tick(gAnno,pB,inN,bOff-16,bOff+20,'#000');
      doubleArrow(gAnno,{x:pA.x+inN.x*bOff,y:pA.y+inN.y*bOff},{x:pB.x+inN.x*bOff,y:pB.y+inN.y*bOff},'#000',2.6,15);
      mathText(gLabels,mid.x+inN.x*(bOff+34),mid.y+inN.y*(bOff+34)+10,PARTS.ds,32,{anchor:'middle'});
    }

    /* ---- Mass ΔM_k caption ---- */
    var mN = (MODE==='geom') ? nm : inN;
    var cap={x:mid.x+mN.x*118, y:mid.y+mN.y*118};
    cap.x=Math.max(120,Math.min(660,cap.x)); cap.y=Math.max(120,Math.min(900,cap.y));
    gAnno.line(cap.x,cap.y-10,mid.x+mN.x*26,mid.y+mN.y*26).stroke({color:'#000',width:2});
    head(gAnno,mid.x+mN.x*22,mid.y+mN.y*22,mid.x-cap.x,mid.y-cap.y,14,'#000');
    mathText(gLabels,cap.x,cap.y+12,PARTS.mass,30,{anchor:'middle'});

    /* ---- point labels ---- */
    labelAt(0,PARTS.P0,{fx:4,fy:56,anchor:'middle'});
    labelAt(L,PARTS.Q,{fx:-6,fy:-34,anchor:'middle'});
    var side = (MODE==='geom')?1:-1;
    if(N<=16){
      [1,2,3].forEach(function(idx){
        if(idx<N && idx!==K-1 && idx!==K) labelAt(sArr[idx],P_(String(idx)),{side:side,off:36});
      });
      if(N-1>3 && N-1!==K-1 && N-1!==K) labelAt(sArr[N-1],PARTS.Pn1,{side:side,off:38});
    }
    labelAt(s1,PARTS.Pk1,{side:side,off:38,back:true});
    labelAt(s2,PARTS.Pk,{side:side,off:110,leader:true});

    /* ---- ribbon zoom arrow ---- */
    var A={x:mid.x+nm.x*20,y:mid.y+nm.y*20}, B={x:752,y:672};
    var C={x:(A.x+B.x)/2+130,y:(A.y+B.y)/2-110};
    var poly=ribbonPath(A,C,B,9,34,2.0);
    var rib=gRibbon.polygon(ptsStr(poly)).fill('#fae3ba').stroke({color:'#b3b3b3',width:3.5,linejoin:'round'}).css('cursor','pointer');
    rib.on('mousemove',function(e){showTooltip('Magnify the kth arc →',e);}).on('mouseleave',hideTooltip);

    /* ---- inset ---- */
    drawInset(arcPts,arcLen,sSample);

    /* ---- panel + legend ---- */
    if(MODE!=='geom') drawLegend();
    if(MODE==='riemann') drawPanel(sArr);
  }

  function labelAt(s,parts,o){
    o=o||{};
    var p=pointAt(s);
    if(o.fx!=null){ mathText(gLabels,p.x+o.fx,p.y+o.fy,parts,34,{anchor:o.anchor||'middle'}); return; }
    var t=tanAt(s), nv=rnorm(t);
    if(o.side<0) nv={x:-nv.x,y:-nv.y};
    var off=o.off||36;
    var q={x:p.x+nv.x*off,y:p.y+nv.y*off};
    if(o.back){ q.x-=t.x*26; q.y-=t.y*26; }
    var anchor = nv.x>0.3?'start':(nv.x<-0.3?'end':'middle');
    var xx=q.x+(anchor==='start'?8:(anchor==='end'?-8:0));
    var yy=q.y+(nv.y>0.3?22:(nv.y<-0.3?-6:11));
    if(o.leader){
      var lp={x:p.x+nv.x*20,y:p.y+nv.y*20};
      gAnno.line(q.x-nv.x*14,q.y-nv.y*14,lp.x,lp.y).stroke({color:'#000',width:2});
      head(gAnno,lp.x,lp.y,lp.x-q.x,lp.y-q.y,14,'#000');
    }
    mathText(gLabels,xx,yy,parts,34,{anchor:anchor});
  }

  function drawInset(arcPts,arcLen,sSample){
    var a=arcPts[0], b=arcPts[arcPts.length-1];
    var ang=Math.atan2(b.y-a.y,b.x-a.x), rot=-0.19-ang;
    var ca=Math.cos(rot), sa=Math.sin(rot), loc=[];
    var minx=1e9,maxx=-1e9,miny=1e9,maxy=-1e9;
    for(var i=0;i<arcPts.length;i++){
      var dx=arcPts[i].x-a.x, dy=arcPts[i].y-a.y;
      var lp={x:dx*ca-dy*sa,y:dx*sa+dy*ca};
      loc.push(lp);
      if(lp.x<minx)minx=lp.x; if(lp.x>maxx)maxx=lp.x;
      if(lp.y<miny)miny=lp.y; if(lp.y>maxy)maxy=lp.y;
    }
    var bw=Math.max(maxx-minx,1), bh=Math.max(maxy-miny,1);
    var sc=Math.min(340/bw,150/bh,9);
    var cx=(minx+maxx)/2, cy=(miny+maxy)/2, CX=960, CY=866;
    insetPts=loc.map(function(p){return {x:CX+(p.x-cx)*sc,y:CY+(p.y-cy)*sc};});
    insetCum=[0];
    for(var j=1;j<insetPts.length;j++)
      insetCum.push(insetCum[j-1]+Math.hypot(insetPts[j].x-insetPts[j-1].x,insetPts[j].y-insetPts[j-1].y));

    gInset.polyline(ptsStr(insetPts)).fill('none').stroke({color:BLUE,width:9,linecap:'round',linejoin:'round'});
    var st=insetPts[0], en=insetPts[insetPts.length-1];
    gInset.circle(24).center(st.x,st.y).fill(BLUE);
    gInset.circle(24).center(en.x,en.y).fill(BLUE);
    mathText(gLabels,st.x-6,st.y+54,PARTS.Pk1,34,{anchor:'middle'});
    mathText(gLabels,en.x+26,en.y+12,PARTS.Pk,34,{anchor:'start'});

    /* inset Δs bracket */
    var minY=1e9; insetPts.forEach(function(p){ if(p.y<minY) minY=p.y; });
    var yBr=minY-62, up={x:0,y:-1};
